import type { Metadata } from "next";

import type { Locale } from "@/i18n/config";
import {
  absoluteLocalizedUrl,
  hreflangLanguages,
  URL_DEFAULT_LOCALE,
} from "@/lib/seo/locale-url";
import { absoluteUrl, isNonProductionIndexing } from "@/lib/seo/site-url";

export const OG_LOCALE: Record<Locale, string> = {
  en: "en_US",
  ar: "ar_AR",
};

/** Generated by `src/app/opengraph-image.tsx` (1200×630). */
export const DEFAULT_OG_IMAGE_PATH = "/opengraph-image";
export const ORGANIZATION_LOGO_PATH = "/images/brand/agenda-logo.png";

type BuildPageMetadataInput = {
  locale: Locale;
  pathname: string;
  title: string;
  description: string;
  /** Locales that have real translations for this page. */
  availableLocales?: readonly Locale[];
  /** Extra query params kept on canonical (rarely used). */
  canonicalSearchParams?: Record<string, string | undefined | null>;
  ogType?: "website" | "article";
  ogImage?: string | null;
  publishedTime?: string | null;
  modifiedTime?: string | null;
  authors?: string[];
  siteName: string;
  /** Force noindex (filters, previews, missing content). */
  noIndex?: boolean;
};

export function buildPageMetadata(input: BuildPageMetadataInput): Metadata {
  const available = input.availableLocales?.length
    ? input.availableLocales
    : ([input.locale] as const);
  const canonical = absoluteLocalizedUrl(
    input.pathname,
    input.locale,
    input.canonicalSearchParams,
  );
  const languages = hreflangLanguages(
    input.pathname,
    available,
    input.canonicalSearchParams,
  );
  const imageUrl = absoluteUrl(input.ogImage || DEFAULT_OG_IMAGE_PATH);
  const blockIndexing = input.noIndex || isNonProductionIndexing();

  const alternateLocales = available.filter((l) => l !== input.locale);

  return {
    title: input.title,
    description: input.description,
    metadataBase: new URL(absoluteUrl("/")),
    alternates: {
      canonical,
      languages,
    },
    robots: blockIndexing
      ? { index: false, follow: true }
      : {
          index: true,
          follow: true,
          googleBot: {
            index: true,
            follow: true,
            "max-image-preview": "large",
            "max-snippet": -1,
            "max-video-preview": -1,
          },
        },
    openGraph: {
      type: input.ogType ?? "website",
      url: canonical,
      title: input.title,
      description: input.description,
      siteName: input.siteName,
      locale: OG_LOCALE[input.locale],
      alternateLocale: alternateLocales.map((l) => OG_LOCALE[l]),
      images: [
        {
          url: imageUrl,
          width: 1200,
          height: 630,
          alt: input.title,
        },
      ],
      ...(input.ogType === "article"
        ? {
            publishedTime: input.publishedTime ?? undefined,
            modifiedTime: input.modifiedTime ?? undefined,
            authors: input.authors,
          }
        : {}),
    },
    twitter: {
      card: "summary_large_image",
      title: input.title,
      description: input.description,
      images: [imageUrl],
    },
  };
}

export function titleWithSite(pageTitle: string, siteName: string): string {
  const trimmed = pageTitle.trim();
  if (!trimmed) return siteName;
  if (trimmed.toLowerCase().includes(siteName.toLowerCase())) return trimmed;
  return `${trimmed} | ${siteName}`;
}

export function localeFromUrlDefault(locale: Locale): boolean {
  return locale === URL_DEFAULT_LOCALE;
}
